CREATE OR REPLACE FUNCTION constructor_release_allowed(release uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,pedpsy,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM pedpsy.instrument_releases r WHERE r.id=release AND r.method_id='tki_ru_30_pairs'
   AND r.form_id='tki_ru_30_pairs_shared' AND r.form_version='0.1.0-draft' AND r.method_version_id='tki_ru_30_pairs@1.0.0'
   AND r.handler_version='tki-contract-0.3.0' AND r.contract_version='1.0' AND r.verification_state='key_verified' AND r.publication_state='draft'
   AND r.form_digest='sha256:10ea2173315f8c74091ec7f619fba7fe8d0ccfa005330cee8720054332daaad7'
   AND r.key_digest='sha256:45bc0c8a1b3f154fb3da5df629da6c42613609633594c4f5f54014a301cded7d'
   AND (SELECT count(*) FROM pedpsy.release_items i WHERE i.release_id=r.id)=30) OR EXISTS(SELECT 1 FROM pedpsy.instrument_releases r WHERE r.id=release AND r.method_id='reflexivity_karpov_27' AND r.method_version_id='reflexivity_karpov_27@1.0.0-local' AND r.handler_version='karpov-local-1.0.0' AND r.verification_state='legacy_checked' AND r.publication_state='draft' AND r.form_digest='sha256:d2a082a861ada76c4b982769d1f45cbc162dc21f8be1f7960b1254cbf718d119' AND r.key_digest='sha256:8ab419afb7cc4123bf3297090e15a08c96b55454ff2cd18e2d20e61863ae5d4a' AND (SELECT count(*) FROM pedpsy.release_items WHERE release_id=r.id)=27 AND NOT EXISTS(SELECT 1 FROM pedpsy.release_items i WHERE i.release_id=r.id AND (jsonb_array_length(i.options)<>7 OR i.ordinal>27))) OR EXISTS(SELECT 1 FROM pedpsy.instrument_releases r WHERE r.id=release AND r.method_id='prfq_ru_16_kamskaya_2023' AND r.method_version_id='prfq_ru_16_kamskaya_2023@1.0.0-local' AND r.handler_version='prfq-local-1.0.0' AND r.verification_state='legacy_checked' AND r.publication_state='draft' AND r.form_digest='sha256:5b51fcedb6b20f8a7e17985f3cbdf821f61fbf134d126bf6b9841f82171e55b7' AND r.key_digest='sha256:c6659305e5f89ab8de3835495f6db6e68d8310bbc0aa88fd048c2ca178ceb312' AND (SELECT count(*) FROM pedpsy.release_items WHERE release_id=r.id)=16 AND NOT EXISTS(SELECT 1 FROM pedpsy.release_items i WHERE i.release_id=r.id AND (jsonb_array_length(i.options)<>7 OR i.ordinal>16))) OR EXISTS(SELECT 1 FROM pedpsy.instrument_releases r WHERE r.id=release AND r.method_id='umics_pi_ru_13' AND r.method_version_id='umics_pi_ru_13@1.0.0-local' AND r.handler_version='umics-local-1.0.0' AND r.verification_state='legacy_checked' AND r.publication_state='draft' AND r.form_digest='sha256:e572a862568690a7ded42d6f49b7b0fb62eb037e40ec91c2c1830ef5d881a480' AND r.key_digest='sha256:ec8ab7814acb36e819adaa728dcb223b7733c3a4d47c90dd434fdaa402250b83' AND (SELECT count(*) FROM pedpsy.release_items WHERE release_id=r.id)=13 AND NOT EXISTS(SELECT 1 FROM pedpsy.release_items i WHERE i.release_id=r.id AND (i.ordinal>13 OR i.options IS DISTINCT FROM r.form_snapshot->'items'->(i.ordinal-1)->'options'))) OR EXISTS(SELECT 1 FROM pedpsy.instrument_releases r WHERE r.id=release AND r.method_id='fras_ru_34_gusarova_2021' AND r.method_version_id='fras_ru_34_gusarova_2021@1.0.0-local' AND r.handler_version='legacy-numeric-1.0.0' AND r.verification_state='legacy_checked' AND r.publication_state='draft' AND r.form_digest='sha256:34294ed246c39b6a65129d593b635f23aea2db1584e80eebe11343d4097a9632' AND r.key_digest='sha256:85fcdec8ea89441c1fea362df394d4c8cdcd9b7c05758b7d79c7571f6489bdc4' AND (SELECT count(*) FROM pedpsy.release_items WHERE release_id=r.id)=34 AND NOT EXISTS(SELECT 1 FROM pedpsy.release_items i WHERE i.release_id=r.id AND (i.ordinal>34 OR i.options IS DISTINCT FROM r.form_snapshot->'items'->(i.ordinal-1)->'options'))) OR EXISTS(SELECT 1 FROM pedpsy.instrument_releases r WHERE r.id=release AND r.method_id='ffmq_39_yumartova_grishina' AND r.method_version_id='ffmq_39_yumartova_grishina@1.0.0-local' AND r.handler_version='legacy-numeric-1.0.0' AND r.verification_state='legacy_checked' AND r.publication_state='draft' AND r.form_digest='sha256:9086d017f43d58fd72d0ae473a62a8259a2a640354737cecdd959aaec6d117e4' AND r.key_digest='sha256:d074490c6a07238679ca2a96df0926b5c7c5ef6ffbf7073f8b09d4f334380188' AND (SELECT count(*) FROM pedpsy.release_items WHERE release_id=r.id)=39 AND NOT EXISTS(SELECT 1 FROM pedpsy.release_items i WHERE i.release_id=r.id AND (i.ordinal>39 OR i.options IS DISTINCT FROM r.form_snapshot->'items'->(i.ordinal-1)->'options'))) OR EXISTS(SELECT 1 FROM pedpsy.instrument_releases r WHERE r.id=release AND r.method_id='parental_anxiety_prikhozhan_40' AND r.method_version_id='parental_anxiety_prikhozhan_40@1.0.0-local' AND r.handler_version='legacy-numeric-1.0.0' AND r.verification_state='legacy_checked' AND r.publication_state='draft' AND r.form_digest='sha256:e80591a035f9dc436ea29ebca59aad3143219258cd2449695c