CREATE OR REPLACE FUNCTION guard_assignment() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pedpsy AS $$
BEGIN
  IF TG_OP IN ('UPDATE','DELETE') AND EXISTS(SELECT 1 FROM pedpsy.attempts WHERE assignment_id=OLD.id) THEN
    IF TG_OP='DELETE' OR (NEW.id,NEW.study_id,NEW.group_id,NEW.stage_id,NEW.release_id) IS DISTINCT FROM (OLD.id,OLD.study_id,OLD.group_id,OLD.stage_id,OLD.release_id)
      THEN RAISE EXCEPTION 'assignment scope is frozen' USING ERRCODE='23514'; END IF;
  END IF;
  IF TG_OP<>'DELETE' AND (SELECT count(*) FROM pedpsy.release_items WHERE release_id=NEW.release_id)<>(CASE WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='reflexivity_karpov_27' THEN 27 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='prfq_ru_16_kamskaya_2023' THEN 16 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='umics_pi_ru_13' THEN 13 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='fras_ru_34_gusarova_2021' THEN 34 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='ffmq_39_yumartova_grishina' THEN 39 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='parental_anxiety_prikhozhan_40' THEN 40 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='fad_r_53_sadovnikova' THEN 53 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='faces_iv_62' THEN 62 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='fhs_lf_32_ru' THEN 32 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='odrev_zakharova_66' THEN 66 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='sspm_2020_28' THEN 28 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='gses_10' THEN 10 ELSE 30 END) THEN RAISE EXCEPTION 'release requires its pinned item count' USING ERRCODE='23514'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $$;
CREATE OR REPLACE FUNCTION guard_attempt() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,pedpsy AS $$
BEGIN
  IF TG_OP='INSERT' THEN IF NEW.status<>'draft' THEN RAISE EXCEPTION 'new attempt must be draft' USING ERRCODE='23514'; END IF; RETURN NEW; END IF;
  IF OLD.status='completed' THEN RAISE EXCEPTION 'completed attempt is immutable' USING ERRCODE='23514'; END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  IF (NEW.id,NEW.study_id,NEW.enrollment_id,NEW.assignment_id,NEW.group_id,NEW.stage_id,NEW.release_id) IS DISTINCT FROM
    (OLD.id,OLD.study_id,OLD.enrollment_id,OLD.assignment_id,OLD.group_id,OLD.stage_id,OLD.release_id) THEN RAISE EXCEPTION 'attempt scope is frozen' USING ERRCODE='23514'; END IF;
  IF NEW.status='completed' THEN
    IF (SELECT count(*) FROM pedpsy.responses WHERE attempt_id=OLD.id)<>(CASE WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='reflexivity_karpov_27' THEN 27 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='prfq_ru_16_kamskaya_2023' THEN 16 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='umics_pi_ru_13' THEN 13 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='fras_ru_34_gusarova_2021' THEN 34 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='ffmq_39_yumartova_grishina' THEN 39 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='parental_anxiety_prikhozhan_40' THEN 40 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='fad_r_53_sadovnikova' THEN 53 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='faces_iv_62' THEN 62 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='fhs_lf_32_ru' THEN 32 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='odrev_zakharova_66' THEN 66 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='sspm_2020_28' THEN 28 WHEN (SELECT method_id FROM pedpsy.instrument_releases WHERE id=NEW.release_id)='gses_10' THEN 10 ELSE 30 END) OR NEW.revision<>OLD.revision+1 OR NOT EXISTS
      (SELECT 1 FROM pedpsy.attempt_results WHERE id=NEW.completion_result_id AND attempt_id=OLD.id AND input_revision=OLD.revision)
      THEN RAISE EXCEPTION 'completion requires full snapshot and matching result' USING ERRCODE='23514'; END IF;
  END IF;
  RETURN NEW;
END $$;
REVOKE ALL ON FUNCTION guard_assignment(),guard_attempt() FROM PUBLIC;
